def inspect_frames(mapping):
    if 'frames' not in mapping:
        return {'ok': False, 'frames': None}
    frames = mapping['frames']
    if frames is None:
        return {'ok': False, 'frames': None}
    if type(frames) is not list:
        return {'ok': False, 'frames': None}
    valid = type(frames) is list and 0 <= len(frames) <= 2
    if valid:
        for frame in frames:
            if type(frame) is not dict or set(frame) != {'toggles'}:
                valid = False
                break
            toggles = frame['toggles']
            if not (type(toggles) is list and 0 <= len(toggles) <= 2):
                valid = False
                break
            for toggle in toggles:
                if type(toggle) is not bool:
                    valid = False
                    break
    if not valid:
        return {'ok': False, 'frames': []}
    return {'ok': True, 'frames': frames}
